<?php
namespace Delnavazan\Platform\Core\Application; use Delnavazan\Platform\Core\Infrastructure\Repository\{EnrolmentRepository,TermRepository};
final class TermService { public function create(array $d):int{if(!current_user_can('dzn_manage_terms'))throw new \RuntimeException('Unauthorized');$d['enrolment_id']=Normalizer::id($d['enrolment_id']??null);if(!(new EnrolmentRepository)->usable($d['enrolment_id']))throw new \InvalidArgumentException('Usable Enrolment required');$d['status']=Normalizer::one($d['status']??'draft',['draft','awaiting_payment','active','completed','cancelled'],'term state');$d['sequence_number']=Normalizer::count($d['sequence_number']??0,1);$d['lesson_allocation']=Normalizer::count($d['lesson_allocation']??12,1);$d['replacement_allowance']=Normalizer::count($d['replacement_allowance']??2,0);$d['payment_state']=Normalizer::one($d['payment_state']??'not_required',['not_required','pending','paid','failed','refunded'],'payment state');$repo=new TermRepository;if($repo->sequenceExists($d['enrolment_id'],$d['sequence_number']))throw new \InvalidArgumentException('Term sequence already exists');return Creator::create($repo,$d,'DZN-TRM-');} }
